package nl.johninnl.vela;

import static org.junit.Assert.*;
import android.media.AudioManager;
import android.os.*;
import android.speech.tts.*;
import java.util.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import nl.johninnl.navigation.alerts.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=32,manifest=Config.NONE)
public class VelaWarningSpeakerTest {
    VelaWarningSpeaker speaker; Guide guide; Engine engine; Results results;
    @Before public void setup(){engine=new Engine();guide=new Guide(engine);speaker=new VelaWarningSpeaker();speaker.bind(guide);results=new Results();}
    @After public void cleanup(){speaker.close();engine.shutdown();Shadows.shadowOf(Looper.getMainLooper()).idle();}
    public static class Engine extends TextToSpeech {
        int calls,leadCalls,result=SUCCESS;String text,id;Locale language;Voice selected;
        Engine(){super(RuntimeEnvironment.getApplication(),null);}
        @Override public int isLanguageAvailable(Locale locale){return locale.getLanguage().equals("nl")||locale.getLanguage().equals("en")?LANG_AVAILABLE:LANG_NOT_SUPPORTED;}
        @Override public Set<Voice> getVoices(){return new HashSet<>(Arrays.asList(new Voice("nl-offline",Locale.forLanguageTag("nl-NL"),400,100,false,Collections.emptySet()),new Voice("en-offline",Locale.US,400,100,false,Collections.emptySet())));}
        @Override public Voice getVoice(){return selected;}
        @Override public int setVoice(Voice voice){selected=voice;return SUCCESS;}
        @Override public boolean isSpeaking(){return false;}
        @Override public int setLanguage(Locale locale){language=locale;return isLanguageAvailable(locale);}
        @Override public int playSilentUtterance(long ms,int queue,String id){leadCalls++;assertEquals(QUEUE_ADD,queue);assertTrue(id.startsWith("vela-lead-warning-"));return SUCCESS;}
        @Override public int speak(CharSequence text,int queue,Bundle b,String id){calls++;this.text=text.toString();this.id=id;assertEquals(QUEUE_ADD,queue);return result;}
    }
    public static class Guide {
        public TextToSpeech b;public float d=.7f;public boolean e=true,h=true,i=false,m=false,n=false,o=false;public int s,releases,request=AudioManager.AUDIOFOCUS_REQUEST_GRANTED;
        public Object p=new Object();public String j="en",preflightLanguage;public Collection<Object> g=new ArrayList<>();public Closure closure;
        Guide(Engine engine){b=engine;}
        public boolean b(){s++;VelaWarningSpeaker.focusRequest(this);VelaWarningSpeaker.focusResult(this,request);return true;}
        public void j(String text,boolean interrupt,boolean ignoreMute){assertFalse(interrupt);assertFalse(ignoreMute);preflightLanguage=VelaWarningSpeaker.language(this,"fr");b();closure=new Closure(this,b);VelaWarningSpeaker.capture(closure);}
        public void f(){releases++;if(s>0)s--;}
    }
    public static class Closure {public byte f=1;public Object h,i;Closure(Guide g,TextToSpeech t){h=g;i=t;}}
    public static class NativeListener {public Object a;NativeListener(Guide g){a=g;}}
    static class Results implements VelaWarningSpeaker.Listener {int starts;List<PlaybackGrant.Outcome> outcomes=new ArrayList<>();List<Boolean> quiet=new ArrayList<>();public void started(PlaybackGrant g){starts++;}public void finished(PlaybackGrant g,PlaybackGrant.Outcome o,boolean q){outcomes.add(o);quiet.add(q);}}
    WarningEvent event(){long now=SystemClock.elapsedRealtime();Bundle b=new Bundle();b.putInt("protocol_version",1);b.putString("provider_session",UUID.randomUUID().toString());b.putLong("sequence",1);b.putString("operation","ANNOUNCE");b.putString("warning_id","test-native");b.putLong("revision",1);b.putLong("announcement_index",1);b.putString("phase","notice");b.putString("native_type","Incident");b.putString("category","road_danger");b.putInt("priority",0);b.putString("message","Synthetische testwaarschuwing");b.putString("language_tag","nl-NL");b.putString("message_origin","native_text");b.putString("relevance","notice");b.putString("relationship","unknown");b.putLong("observed_elapsed_ms",now);b.putLong("issued_elapsed_ms",now);b.putLong("announce_until_elapsed_ms",now+5000);b.putLong("state_until_elapsed_ms",now+30000);return WarningCodec.decode(b,now);}
    PlaybackGrant grant(WarningEvent e){return grant(e,WarningAudioOwner.Mode.VOICE);}
    PlaybackGrant grant(WarningEvent e,WarningAudioOwner.Mode mode){return grant(e,mode,null);}
    PlaybackGrant grant(WarningEvent e,WarningAudioOwner.Mode mode,WarningEvent authority){long now=SystemClock.elapsedRealtime();Set<String> caps=Collections.singleton("native_text");WarningCapabilities profile=new WarningCapabilities(String.join("",Collections.nCopies(64,"a")),caps,true);WarningJournal journal=new WarningJournal(e.providerSession);if(authority!=null)journal.append(authority,now);journal.append(e,now);WarningAudioOwner owner=new WarningAudioOwner("boot-count:1",e.providerSession,journal,new PlaybackStore(){public PlaybackGrant load(){return null;}public void save(PlaybackGrant g){}},profile);WarningAudioOwner.Client client=new WarningAudioOwner.Client(10001,"app.vela",UUID.randomUUID().toString(),UUID.randomUUID().toString(),caps,EnumSet.of(WarningAudioOwner.Mode.VOICE,WarningAudioOwner.Mode.TONE),profile.digest);WarningAudioOwner.Lease lease=owner.claim(10001,client,mode,true,now).lease;return owner.begin(10001,client,lease.token,lease.epoch,e.warningId,e.phase,e.announcementIndex,e.revision,UUID.randomUUID().toString(),now).grant;}
    void idle(){Shadows.shadowOf(Looper.getMainLooper()).idle();}
    @Test public void revisedTextKeepsOriginalAnnouncementAuthorityAndDeadline(){WarningEvent authority=event();Bundle changed=WarningCodec.encode(authority);changed.putString("operation","UPSERT");changed.putLong("sequence",2);changed.putLong("revision",2);changed.putString("message","Bijgewerkte synthetische waarschuwing");changed.remove("announce_until_elapsed_ms");WarningEvent payload=WarningCodec.decode(changed,SystemClock.elapsedRealtime());PlaybackGrant grant=grant(payload,WarningAudioOwner.Mode.VOICE,authority);assertFalse(speaker.speak(payload,grant,results));assertTrue(speaker.speak(payload,grant,authority.announceUntil,results));assertTrue(VelaWarningSpeaker.dispatch(guide.closure));assertEquals(payload.message,engine.text);}
    @Test public void expiredOriginalDeadlineCannotBeExtendedByRevisedText(){WarningEvent authority=event();Bundle changed=WarningCodec.encode(authority);changed.putString("operation","UPSERT");changed.putLong("sequence",2);changed.putLong("revision",2);WarningEvent payload=WarningCodec.decode(changed,SystemClock.elapsedRealtime());PlaybackGrant grant=grant(payload,WarningAudioOwner.Mode.VOICE,authority);assertFalse(speaker.speak(payload,grant,SystemClock.elapsedRealtime(),results));assertEquals(0,engine.calls);}
    @Test public void selectedEngineAndLanguagePreserveNativeTextAndEnqueueIsNotStart(){WarningEvent e=event();PlaybackGrant g=grant(e);assertTrue(speaker.isReady(e.languageTag));assertTrue(speaker.speak(e,g,results));assertEquals(0,engine.calls);assertTrue(VelaWarningSpeaker.dispatch(guide.closure));assertEquals(e.message,engine.text);assertEquals("nl",engine.language.getLanguage());assertEquals("nl-NL",guide.j);assertEquals("nl",guide.preflightLanguage);assertEquals("fr",VelaWarningSpeaker.language(guide,"fr"));assertEquals(0,results.starts);assertTrue(VelaWarningSpeaker.utterance(new NativeListener(guide),engine.id,0));idle();assertEquals(1,results.starts);assertTrue(VelaWarningSpeaker.utteranceDone(new NativeListener(guide),engine.id));idle();assertEquals(Collections.singletonList(PlaybackGrant.Outcome.COMPLETED),results.outcomes);assertEquals(1,guide.releases);assertFalse(speaker.speak(e,g,results));}
    @Test public void pendingCancelRejectsClosureAndBalancesOnlyItsAcquisition(){WarningEvent e=event();PlaybackGrant g=grant(e);assertTrue(speaker.speak(e,g,results));speaker.cancel(g);assertTrue(VelaWarningSpeaker.dispatch(guide.closure));idle();assertEquals(0,engine.calls);assertEquals(1,guide.releases);assertEquals(Collections.singletonList(PlaybackGrant.Outcome.CANCELLED),results.outcomes);assertEquals(Collections.singletonList(true),results.quiet);VelaWarningSpeaker.dispatch(guide.closure);assertEquals(1,guide.releases);}
    @Test public void nativeStopInvalidatesLeadWithoutDecrementingNewNativeRoute(){WarningEvent e=event();assertTrue(speaker.speak(e,grant(e),results));VelaWarningSpeaker.nativeStop(guide);guide.s=1;VelaWarningSpeaker.dispatch(guide.closure);idle();assertEquals(0,engine.calls);assertEquals(0,guide.releases);assertEquals(1,guide.s);}
    @Test public void deniedOrDelayedFocusNeverSubmitsSpeech(){for(int focus:new int[]{AudioManager.AUDIOFOCUS_REQUEST_FAILED,AudioManager.AUDIOFOCUS_REQUEST_DELAYED}){guide.request=focus;WarningEvent e=event();assertTrue(speaker.speak(e,grant(e),results));VelaWarningSpeaker.dispatch(guide.closure);idle();assertEquals(0,engine.calls);assertEquals(PlaybackGrant.Outcome.NOT_STARTED,results.outcomes.get(results.outcomes.size()-1));}}
    @Test public void submittedCancellationRetainsFenceUntilActualTerminalAndLateStartIsNotAccepted(){WarningEvent e=event();PlaybackGrant g=grant(e);speaker.speak(e,g,results);VelaWarningSpeaker.dispatch(guide.closure);String id=engine.id;speaker.cancel(g);VelaWarningSpeaker.utteranceStart(new NativeListener(guide),id);idle();assertEquals(0,results.starts);assertEquals(Collections.singletonList(false),results.quiet);assertFalse(speaker.isReady(e.languageTag));VelaWarningSpeaker.utteranceStopped(new NativeListener(guide),id);idle();assertEquals(Arrays.asList(false,true),results.quiet);assertTrue(speaker.isReady(e.languageTag));assertEquals(1,guide.releases);VelaWarningSpeaker.utteranceDone(new NativeListener(guide),id);assertEquals(1,guide.releases);}
    @Test public void nativeStopAfterSubmissionAndLateTerminalCannotReleaseANewerRoute(){WarningEvent e=event();speaker.speak(e,grant(e),results);VelaWarningSpeaker.dispatch(guide.closure);String id=engine.id;VelaWarningSpeaker.nativeStop(guide);guide.s=1;VelaWarningSpeaker.utteranceStopped(new NativeListener(guide),id);idle();assertEquals(0,guide.releases);assertEquals(1,guide.s);assertEquals(Arrays.asList(false,true),results.quiet);}
    @Test public void submissionFailureAndModeCapsAreTruthful(){engine.result=TextToSpeech.ERROR;WarningEvent e=event();speaker.speak(e,grant(e),results);VelaWarningSpeaker.dispatch(guide.closure);idle();assertEquals(Collections.singletonList(PlaybackGrant.Outcome.FAILED),results.outcomes);assertEquals(Collections.singletonList(true),results.quiet);guide.n=true;guide.o=true;assertEquals(WarningAudioOwner.Mode.TONE,speaker.effectiveMode(WarningAudioOwner.Mode.VOICE));assertTrue(speaker.isReady("nl",WarningAudioOwner.Mode.TONE));guide.o=false;assertEquals(WarningAudioOwner.Mode.SILENT,speaker.effectiveMode(WarningAudioOwner.Mode.VOICE));guide.n=false;guide.m=true;assertFalse(speaker.isReady("nl"));}
    @Test public void nativeRouteArrivalCancelsOnlyOwnedToneAndBalancesNativeFocus(){guide.n=true;guide.o=true;WarningEvent e=event();PlaybackGrant g=grant(e,WarningAudioOwner.Mode.TONE);assertTrue(speaker.speak(e,g,results));VelaWarningSpeaker.nativeSpeech(guide);idle();assertEquals(PlaybackGrant.Outcome.CANCELLED,results.outcomes.get(0));assertTrue(results.quiet.get(0));assertEquals(1,guide.releases);assertEquals(0,engine.calls);}
    @Test public void toneRetainsNativePcmEnvelopeAndGap(){short[] pcm=VelaWarningSpeaker.tonePcm();int note=22050*110/1000;assertEquals(note*2+661,pcm.length);assertEquals(0,pcm[0]);assertEquals(0,pcm[note-1]);for(int i=note;i<note+661;i++)assertEquals(0,pcm[i]);assertArrayEquals(Arrays.copyOfRange(pcm,0,note),Arrays.copyOfRange(pcm,note+661,pcm.length));int peak=0;for(short sample:pcm)peak=Math.max(peak,Math.abs((int)sample));assertTrue(peak>9000 && peak<=9500);}
    @Test public void untaggedNativeClosuresAndListenerIdsKeepOriginalPath(){assertFalse(VelaWarningSpeaker.dispatch(new Closure(guide,engine)));assertFalse(VelaWarningSpeaker.utteranceDone(new NativeListener(guide),"vela-12345"));assertEquals(0,guide.releases);}
}
